export const inputSchema = z.object({
  target_url: z.string().url(),
  org_slug: z.string().min(1).regex(/^[a-z0-9][a-z0-9-_]*$/i, 'org_slug must be a slug (letters, digits, - and _)'),
  max_pages: z.number().int().min(1).max(50).default(15),   // rendered pages only; 404s and navigation failures are free
  auth: z.discriminatedUnion('type', [   // basic → httpCredentials, cookie → context.addCookies
    z.object({ type: z.literal('basic'), username: z.string(), password: z.string() }),
    z.object({ type: z.literal('cookie'), cookies: z.array(z.object({ name: z.string(), value: z.string(), domain: z.string() })).min(1) }),
  ]).optional(),
  headless: z.boolean().default(true),
  timeout_ms: z.number().int().min(1000).max(120_000).default(15_000),   // per navigation, also used as the context default timeout
  mcp: z.boolean().default(true),   // false = no .mcp.json and no `mcp` npm script in the generated project
});

/** Canonical form of a URL for the queue: same-origin, no hash, no trailing-slash ambiguity. */
export function normaliseUrl(raw: string, base: string): string | undefined {
  let u: URL;
  try { u = new URL(raw, base); } catch { return undefined; }
  if (u.protocol !== 'http:' && u.protocol !== 'https:') return undefined;
  u.hash = '';   // /about#top and /about are the same page
  if (u.pathname.length > 1 && u.pathname.endsWith('/')) u.pathname = u.pathname.slice(0, -1);   // and so are /about/ and /about
  return u.toString();
}

export function isCrawlable(url: string, origin: string): boolean {
  let u: URL;
  try { u = new URL(url); } catch { return false; }
  if (u.origin !== origin) return false;
  if (ASSET_EXT.test(u.pathname)) return false;   // never render a PDF or a stylesheet as a "page"
  return true;
}

export async function crawl(opts: CrawlOptions): Promise<CrawlResult> {
  const log = opts.log ?? (() => undefined);
  const started = Date.now();
  const startUrl = normaliseUrl(opts.startUrl, opts.startUrl);
  if (!startUrl) throw new Error(`invalid target_url: ${opts.startUrl}`);
  const origin = new URL(startUrl).origin;

  const browser = await chromium.launch({ headless: opts.headless });
  const pages: PageRecord[] = [];
  const brokenLinks: BrokenLink[] = [];
  const skipped: string[] = [];
  try {
    const context = await newContext(browser, opts);
    const page = await context.newPage();
    const queue: { url: string; referrer: string }[] = [{ url: startUrl, referrer: '(start)' }];
    const seen = new Set<string>([startUrl]);
    let visits = 0;

    while (queue.length) {
      const next = queue.shift()!;
      if (pages.length >= opts.maxPages) { skipped.push(next.url); continue; }   // budget 1: rendered pages
      if (visits >= opts.maxPages + MAX_BROKEN_LINK_VISITS) { skipped.push(next.url); continue; }   // budget 2: total visits, so dead-link farms terminate
      visits++;
      log(`recon: visiting ${next.url}`);
      const outcome = await visit(page, next.url, next.referrer, opts);
      if (outcome.page) {
        pages.push(outcome.page);
        log(`recon: ${outcome.page.status} ${outcome.page.title || '(untitled)'} in ${outcome.page.loadTimeMs} ms, ${outcome.page.elements.length} interactive elements`);
        for (const raw of outcome.page.discoveredLinks) {
          const n = normaliseUrl(raw, next.url);
          if (!n || seen.has(n) || !isCrawlable(n, origin)) continue;
          seen.add(n);   // dedupe before enqueue, not after visit
          queue.push({ url: n, referrer: next.url });
        }
      } else if (outcome.broken) {
        brokenLinks.push(outcome.broken);
        log(`recon: broken ${outcome.broken.url} (${outcome.broken.status || outcome.broken.error})`);
      }
    }
    await context.close();
  } finally {
    await browser.close().catch(() => undefined);   // always: a crash mid-crawl must not leak Chromium
  }
  return { origin, startUrl, pages, brokenLinks, skipped, durationMs: Date.now() - started };
}

async function visit(page: Page, url: string, referrer: string, opts: CrawlOptions): Promise<VisitOutcome> {
  const consoleErrors: string[] = [];
  const failedRequests: FailedRequest[] = [];
  const onConsole = (m: { type(): string; text(): string }) => { if (m.type() === 'error') consoleErrors.push(m.text().slice(0, 300)); };
  const onPageError = (e: Error) => consoleErrors.push(`pageerror: ${e.message.slice(0, 300)}`);
  const onResponse = (r: { status(): number; url(): string; request(): { method(): string; resourceType(): string } }) => {
    if (r.status() >= 400 && r.url() !== url) failedRequests.push({ url: r.url(), status: r.status(), method: r.request().method(), resourceType: r.request().resourceType() });   // the page's own 404 is a broken link, not a failed request
  };
  page.on('console', onConsole);
  page.on('pageerror', onPageError);
  page.on('response', onResponse);
  const started = Date.now();
  try {
    const response = await page.goto(url, { waitUntil: 'load', timeout: opts.timeoutMs });
    const loadTimeMs = Date.now() - started;
    const status = response?.status() ?? 200;
    if (status >= 400) return { broken: { url, status, referrer } };   // error pages are never harvested as pages
    // Let late console errors and SPA hydration settle briefly, but never longer than the budget.
    await page.waitForLoadState('networkidle', { timeout: Math.min(2000, opts.timeoutMs) }).catch(() => undefined);   // let SPA hydration settle, but never past the budget
    const harvest = await page.evaluate(`(${HARVEST_SCRIPT})(${MAX_ELEMENTS_PER_PAGE})`) as HarvestResult;   // plain JS string, see next step
    const u = new URL(page.url());
    return {
      page: {
        url,
        path: u.pathname + u.search,
        title: harvest.title,
        status,
        loadTimeMs,
        consoleErrors,
        failedRequests,
        counts: harvest.counts,
        hasLandmark: harvest.hasLandmark,
        hasH1: harvest.hasH1,
        h1Text: harvest.h1Text,
        imagesMissingAlt: harvest.imagesMissingAlt,
        unlabeledInputs: harvest.unlabeledInputs,
        formsWithoutLabels: harvest.formsWithoutLabels,
        elements: buildInteractiveElements(harvest.elements),
        discoveredLinks: harvest.links,
      },
    };
  } catch (err) {
    const message = err instanceof Error ? err.message.split('\n')[0]! : String(err);
    return { broken: { url, status: 0, referrer, error: message } };   // DNS / timeout / TLS → high-severity navigation finding
  } finally {
    page.off('console', onConsole);   // listeners never outlive the visit
    page.off('pageerror', onPageError);
    page.off('response', onResponse);
  }
}

/**
 * Runs inside the browser. Kept as plain JavaScript source (not a TS function) so no transpiler
 * helpers such as esbuild's `__name` leak into the page, and no Node scope is captured.
 * Signature: (maxElements: number) => HarvestResult
 */
export const HARVEST_SCRIPT = String.raw`(maxElements) => {   // plain JS: no esbuild helpers leak into the page
  const norm = (s) => (s ?? '').replace(/\s+/g, ' ').trim();
  const isVisible = (el) => {
    if (el.hidden || el.getAttribute('aria-hidden') === 'true') return false;
    const cs = window.getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') return false;
    return el.getClientRects().length > 0;
  };

  const accName = (el) => {
    const lb = el.getAttribute('aria-labelledby');   // precedence 1
    if (lb) {
      const t = norm(lb.split(/\s+/).map((i) => (document.getElementById(i) || {}).textContent || '').join(' '));
      if (t) return t;
    }
    const al = norm(el.getAttribute('aria-label'));   // precedence 2
    if (al) return al;
    const tag = el.tagName.toLowerCase();

  // …

  const selector = 'a[href], button, input:not([type="hidden"]), select, textarea, summary, [role="button"], [role="link"], [role="tab"], [role="menuitem"], [role="checkbox"], [role="radio"], [role="textbox"], [role="combobox"], [role="switch"], [contenteditable="true"]';   // what counts as interactive
  const elements = [];
  const seen = new Set();
  for (const el of Array.from(document.querySelectorAll(selector))) {
    if (elements.length >= maxElements) break;   // 60 per page
    if (seen.has(el) || !isVisible(el)) continue;
    seen.add(el);
    const tag = el.tagName.toLowerCase();
    const attr = (n) => { const v = el.getAttribute(n); return v === null ? undefined : v; };
    const testId = attr('data-testid') ?? attr('data-test-id') ?? attr('data-test') ?? attr('data-cy');   // four test-id conventions

  // …

  const controls = Array.from(document.querySelectorAll('input:not([type="hidden"]):not([type="submit"]):not([type="button"]):not([type="reset"]):not([type="image"]), select, textarea'));
  const unlabeled = controls.filter((c) => !labelFor(c) && !norm(c.getAttribute('aria-label')) && !c.getAttribute('aria-labelledby') && !norm(c.getAttribute('placeholder')) && !norm(c.getAttribute('title')));   // exactly the controls getByLabel() cannot reach
  const forms = Array.from(document.querySelectorAll('form'));
  const formsWithoutLabels = forms.filter((f) => unlabeled.some((u) => f.contains(u))).length;   // medium finding when > 0

  const imgs = Array.from(document.querySelectorAll('img'));
  const imagesMissingAlt = imgs.filter((i) => !i.hasAttribute('alt') && i.getAttribute('role') !== 'presentation' && i.getAttribute('aria-hidden') !== 'true').length;

  const h1 = document.querySelector('h1');
  const hasLandmark = !!document.querySelector('main, [role="main"], header, [role="banner"], nav, [role="navigation"], footer, [role="contentinfo"]');   // low finding when false

function looksGenerated(s: string): boolean {   // ember123, css-1x2y3z, :r1:, hashes, long digit runs
  // ids/classes like "ember123", "css-1x2y3z", ":r1:", "sc-abc123", pure hashes
  return /^:|^(ember|react|mui|css|sc|jss|svelte|chakra|radix)[-_]?[a-z0-9]{3,}$|^[a-f0-9]{8,}$|\d{4,}/i.test(s);
}

/** Pick the best Playwright locator for an element, in Playwright's recommended priority order. */
export function deriveLocator(el: ElementDescriptor): DerivedLocator {
  const tag = el.tag.toLowerCase();
  const role = el.role?.toLowerCase() || implicitRole(tag, el.type, el.href);
  const name = normaliseText(el.name) ?? normaliseText(el.label) ?? normaliseText(el.text);
  const label = normaliseText(el.label);
  const placeholder = normaliseText(el.placeholder);
  const text = normaliseText(el.text);
  const testId = normaliseText(el.testId);

  if (role && name) {   // Playwright's first choice, and the demo's 8 of 9
    return { strategy: 'role', code: `page.getByRole(${q(role)}, { name: ${q(name)}, exact: true })`, confidence: 'high', role, name };
  }
  if (label) {   // a <label> with no computed role
    return { strategy: 'label', code: `page.getByLabel(${q(label)}, { exact: true })`, confidence: 'high', role, name: label };
  }
  if (placeholder) {   // placeholder-only inputs
    return { strategy: 'placeholder', code: `page.getByPlaceholder(${q(placeholder)}, { exact: true })`, confidence: 'high', role, name: placeholder };
  }
  if (text && ['a', 'button', 'summary', 'label', 'span', 'div', 'li', 'p'].includes(tag)) {
    return { strategy: 'text', code: `page.getByText(${q(text)}, { exact: true })`, confidence: 'medium', role, name: text };
  }
  if (testId) {   // medium: test ids are stable but say nothing to a reader
    return { strategy: 'testid', code: `page.getByTestId(${q(testId)})`, confidence: 'medium', role, name: testId };
  }
  // Role without a name is still better than raw CSS when it is the only such element type.
  if (role && !['link', 'button'].includes(role) && !el.id && !el.nameAttr) {   // the demo's firstInput: medium, and an accessibility finding
    return { strategy: 'role', code: `page.getByRole(${q(role)})`, confidence: 'low', role };
  }
  // CSS fallbacks, most stable first.
  if (el.id && !looksGenerated(el.id)) {
    return { strategy: 'css', code: `page.locator(${q('#' + cssEscapeIdent(el.id))})`, confidence: 'medium', role };
  }
  if (el.nameAttr) {
    return { strategy: 'css', code: `page.locator(${q(`${tag}[name="${el.nameAttr}"]`)})`, confidence: 'medium', role };
  }
  const stableClasses = (el.classes ?? []).filter(c => c && !looksGenerated(c)).slice(0, 2);   // at most two classes, none generated-looking
  if (stableClasses.length) {
    return { strategy: 'css', code: `page.locator(${q(`${tag}.${stableClasses.map(cssEscapeIdent).join('.')}`)})`, confidence: 'low', role };
  }
  const typeSel = el.type ? `${tag}[type="${el.type}"]` : tag;
  return { strategy: 'css', code: `page.locator(${q(typeSel)})`, confidence: 'low', role };
}

export const SLOW_PAGE_MS = 3000;   // > 3 s medium, > 9 s high

export function deriveFindings(crawl: CrawlResult): FindingDraft[] {
  const out: FindingDraft[] = [];

  for (const b of crawl.brokenLinks) {
    if (b.status === 0) {   // DNS / timeout / TLS
      out.push({ severity: 'high', category: 'navigation', title: `Navigation failed: ${b.url}`, detail: `${b.error ?? 'unknown error'} (linked from ${b.referrer})`, evidence: b });
    } else {
      out.push({
        severity: b.status >= 500 ? 'high' : 'medium', category: 'broken-link',   // 5xx high, 4xx medium
        title: `Broken link (${b.status}): ${b.url}`, detail: `Linked from ${b.referrer}`, evidence: b,
      });
    }
  }

  for (const p of crawl.pages) {
    if (p.consoleErrors.length) {
      out.push({
        severity: 'medium', category: 'console-error',   // first 3 messages in detail, all in evidence
        title: `${p.consoleErrors.length} console error${p.consoleErrors.length === 1 ? '' : 's'} on ${p.path}`,
        detail: p.consoleErrors.slice(0, 3).join(' | '), evidence: { url: p.url, errors: p.consoleErrors },
      });
    }
    if (p.failedRequests.length) {
      const worst = Math.max(...p.failedRequests.map(f => f.status));
      out.push({
        severity: worst >= 500 ? 'medium' : 'low', category: 'failed-request',
        title: `${p.failedRequests.length} failed network request${p.failedRequests.length === 1 ? '' : 's'} on ${p.path}`,
        detail: p.failedRequests.slice(0, 3).map(f => `${f.status} ${f.method} ${f.url}`).join(' | '),
        evidence: { url: p.url, requests: p.failedRequests },
      });
    }
    if (p.loadTimeMs > SLOW_PAGE_MS) {
      out.push({
        severity: p.loadTimeMs > SLOW_PAGE_MS * 3 ? 'high' : 'medium', category: 'performance',
        title: `Slow page load (${p.loadTimeMs} ms) on ${p.path}`, detail: `Threshold is ${SLOW_PAGE_MS} ms`, evidence: { url: p.url, load_time_ms: p.loadTimeMs },
      });
    }

  // …

    const lowConfidence = p.elements.filter(e => e.locator.confidence === 'low').length;
    if (lowConfidence > 0 && p.elements.length > 0 && lowConfidence / p.elements.length >= 0.5) {   // half or more fell back to CSS → info
      out.push({
        severity: 'info', category: 'testability',
        title: `${lowConfidence}/${p.elements.length} interactive elements on ${p.path} lack an accessible name or test id`,
        detail: 'Page-object locators fell back to CSS; add accessible names or data-testid attributes',
        evidence: { url: p.url, low_confidence: lowConfidence, total: p.elements.length },
      });
    }
  }

  if (!crawl.pages.length) {
    out.push({ severity: 'critical', category: 'navigation', title: 'No page could be rendered', detail: `The start URL ${crawl.startUrl} did not produce a renderable page; check the URL, network access and authentication`, evidence: { start_url: crawl.startUrl } });   // the only critical: no page rendered at all
  }
  return out;
}

export function generateSmokeSpec(pages: PageRecord[]): string {
  const classNames = assignClassNames(pages);
  const imports = pages.map(p => {
    const cls = classNames.get(p)!;
    return `import { ${cls} } from '../pages/${cls}.page';`;
  }).join('\n');

  const tests = pages.map(p => {
    const cls = classNames.get(p)!;
    const lines: string[] = [];
    lines.push(`  test(${q(specTitle(p))}, async ({ page, consoleErrors }) => {`);
    lines.push(`    const po = new ${cls}(page);`);
    lines.push(`    const response = await po.goto();`);
    lines.push(`    expect(response?.status() ?? 200, 'page should respond successfully').toBeLessThan(400);`);   // the only assertion every page gets
    if (p.title) lines.push(`    await expect(page).toHaveTitle(${q(p.title)});`);   // only when recon saw a title
    if (p.hasH1 && p.h1Text) lines.push(`    await expect(page.getByRole('heading', { level: 1 }).first()).toContainText(${q(p.h1Text.slice(0, 60))});`);
    else if (p.hasH1) lines.push(`    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();`);
    else lines.push(`    // NOTE: recon found no <h1> on this page (see findings). Add one, then assert on it here.`);   // the /about test carries this line
    lines.push(`    expect(consoleErrors, 'no console errors during load').toEqual([]);`);   // the fixture from tests/fixtures.ts
    lines.push(`  });`);
    return lines.join('\n');
  }).join('\n\n');

  return `import { test, expect } from './fixtures';
${imports}

/**
 * Smoke suite generated by The Forward Deployed Tester: one test per page found during
 * reconnaissance. Each test navigates, checks the response, title/h1 and that the console stayed clean.
 */
test.describe('smoke', () => {
${tests}
});
`;
}

  // …

export function generatePageObject(p: PageRecord, className = pageClassName(p.path)): string {
  const props = p.elements.map(el => {
    const d = el.descriptor;
    const desc = [d.tag, d.type ? `type=${d.type}` : '', el.locator.role ?? '', `(${el.locator.strategy}, ${el.locator.confidence} confidence)`]   // doc comment: tag, type, role, strategy, confidence
      .filter(Boolean).join(' ');
    return `  /** ${desc} */\n  get ${el.property}(): Locator { return this.${el.locator.code}; }`;   // one getter per harvested element
  }).join('\n\n');

  return `import type { Page, Locator, Response } from '@playwright/test';

/**
 * Page object for ${p.url}
 * Title: ${(p.title || '(untitled)').replace(/\*\//g, '* /')}
 * Generated by The Forward Deployed Tester from the accessibility tree. Review low-confidence locators.
 */
export class ${className} {
  readonly path = ${q(p.path)};

  constructor(readonly page: Page) {}

  async goto(): Promise<Response | null> {
    return this.page.goto(this.path);
  }
${props ? '\n' + props + '\n' : ''}}
`;
}

  // …

export function generateInfra(pages: PageRecord[], opts: InfraOptions): GeneratedFile[] {
  const classNames = assignClassNames(pages);
  const files: GeneratedFile[] = [
    { relPath: 'package.json', content: generatePackageJson(opts), kind: 'infra/package' },
    { relPath: 'playwright.config.ts', content: generatePlaywrightConfig(opts), kind: 'infra/config' },
    { relPath: 'tests/fixtures.ts', content: generateFixtures(), kind: 'infra/fixture' },
    { relPath: 'tests/smoke.spec.ts', content: generateSmokeSpec(pages), kind: 'infra/spec' },   // every file becomes an artifacts row with its kind
    { relPath: 'README.md', content: generateReadme(pages, opts), kind: 'infra/readme' },
    { relPath: '.github/workflows/playwright.yml', content: generateWorkflow(), kind: 'infra/ci' },
    { relPath: '.gitignore', content: 'node_modules/\ntest-results/\nplaywright-report/\nblob-report/\nplaywright/.cache/\n', kind: 'infra/misc' },
  ];
  if (opts.mcp) files.push({ relPath: '.mcp.json', content: generateMcpJson(opts), kind: 'infra/mcp' });   // .mcp.json only when requested
  for (const p of pages) {
    const cls = classNames.get(p)!;
    files.push({ relPath: `pages/${pageFileName(cls)}`, content: generatePageObject(p, cls), kind: 'infra/page-object' });
  }
  return files;
}

  // d. Report
  ctx.log('phase 4/4 report');
  const fallback = deterministicSummary(result, findings);   // always computed first
  const summary = await maybeLlm(async (llm) => {   // no model reachable → fallback, model throws → fallback
    const text = await llm.complete(
      `Rewrite this QA executive summary in two or three crisp sentences for an engineering manager. Keep every number exactly as given. Do not add facts.\n\n${fallback}`,   // the model may only rephrase
      { system: 'You are a senior QA lead writing a short, factual executive summary.', maxTokens: 300 },
    );
    const cleaned = text.trim();
    return cleaned.length > 40 && cleaned.length < 1200 ? cleaned : fallback;   // length guard
  }, fallback);

  const reportInput = {
    orgSlug: input.org_slug, targetUrl: input.target_url, runId: ctx.runId, generatedAt,
    crawl: result, findings, infraDir, infraFiles: files.map(f => f.relPath), summary,
  };
  const reportPath = path.join(ctx.workspaceDir, 'report.md');
  const reportJsonPath = path.join(ctx.workspaceDir, 'report.json');
  fs.writeFileSync(reportPath, renderReportMarkdown(reportInput));
  fs.writeFileSync(reportJsonPath, JSON.stringify(buildReportJson(reportInput), null, 2));
  ctx.db.addArtifact({ run_id: ctx.runId, kind: 'report/markdown', path: reportPath });
  ctx.db.addArtifact({ run_id: ctx.runId, kind: 'report/json', path: reportJsonPath });
  ctx.log(`report written to ${reportPath}`);

  // …

/** Deterministic executive summary used when no model is configured. */
export function deterministicSummary(crawl: CrawlResult, findings: Pick<Finding, 'severity'>[]): string {
  const counts = countBySeverity(findings);
  const pages = crawl.pages.length;
  const locs = totalLocators(crawl.pages);
  const slow = crawl.pages.filter(p => p.loadTimeMs > 3000).length;
  const avg = pages ? Math.round(crawl.pages.reduce((n, p) => n + p.loadTimeMs, 0) / pages) : 0;
  const parts = [
    `Crawled ${pages} page${pages === 1 ? '' : 's'} on ${crawl.origin} in ${(crawl.durationMs / 1000).toFixed(1)} s (avg load ${avg} ms${slow ? `, ${slow} slow` : ''}).`,
    `Recorded ${findings.length} finding${findings.length === 1 ? '' : 's'}: ${counts.critical} critical, ${counts.high} high, ${counts.medium} medium, ${counts.low} low, ${counts.info} info.`,
    crawl.brokenLinks.length ? `${crawl.brokenLinks.length} same-origin link${crawl.brokenLinks.length === 1 ? '' : 's'} answered 4xx/5xx or failed to load.` : 'No broken same-origin links found.',
    `Provisioned a Playwright + MCP project with ${pages} page object${pages === 1 ? '' : 's'}, ${locs} locators and ${pages} smoke test${pages === 1 ? '' : 's'}.`,   // every figure comes from the crawl result
    crawl.skipped.length ? `${crawl.skipped.length} discovered link${crawl.skipped.length === 1 ? '' : 's'} not visited (max_pages reached); raise max_pages for fuller coverage.` : '',
  ];
  return parts.filter(Boolean).join(' ');
}
